'use client';

// SPDX-License-Identifier: MIT
// Copyright (c) 2026 Web Stylebook

import { useId, type ComponentPropsWithRef, type ReactNode } from 'react';
import '../theme.css';
import './switch.css';

function cx(...parts: Array<string | false | null | undefined>) {
  return parts.filter(Boolean).join(' ');
}

export interface SwitchProps extends Omit<ComponentPropsWithRef<'input'>, 'type' | 'checked' | 'defaultChecked' | 'onChange' | 'role'> {
  label: ReactNode;
  /** One line under the label. Screen readers read it after the name. */
  description?: ReactNode;
  checked: boolean;
  onCheckedChange: (checked: boolean) => void;
}

/** An on/off setting that applies at once. Inside a form that saves later, use a Checkbox. */
export function Switch({ label, description, checked, onCheckedChange, disabled, className, ...rest }: SwitchProps) {
  const labelId = useId();
  const descriptionId = useId();

  return (
    <label className={cx('ws-switch', className)} data-disabled={disabled ? '' : undefined}>
      <input
        {...rest}
        className="ws-switch__input"
        type="checkbox"
        role="switch"
        checked={checked}
        disabled={disabled}
        aria-labelledby={labelId}
        aria-describedby={description ? descriptionId : undefined}
        onChange={(event) => onCheckedChange(event.target.checked)}
      />
      <span className="ws-switch__track" aria-hidden="true">
        <span className="ws-switch__thumb" />
      </span>
      <span className="ws-switch__text">
        <span className="ws-switch__label" id={labelId}>
          {label}
        </span>
        {description ? (
          <span className="ws-switch__description" id={descriptionId}>
            {description}
          </span>
        ) : null}
      </span>
    </label>
  );
}

/* SPDX-License-Identifier: MIT. Copyright (c) 2026 Web Stylebook */

/* The native checkbox stays in the page, invisible and on top of the track,
   so focus, form behavior, and the switch role all come from the browser. */

.ws-switch {
  --ws-switch-width: 44px;
  --ws-switch-height: 24px;
  --ws-switch-thumb: 20px;
  --ws-switch-pad: 2px;
  --ws-switch-travel: calc(var(--ws-switch-width) - var(--ws-switch-thumb) - (var(--ws-switch-pad) * 2));
  position: relative;
  box-sizing: border-box;
  display: inline-flex;
  align-items: center;
  gap: var(--ws-space-3);
  min-height: var(--ws-target-min);
  color: var(--ws-color-text);
  font-family: var(--ws-font-sans);
  font-size: var(--ws-text-md);
  line-height: var(--ws-leading-tight);
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}

.ws-switch[data-disabled] {
  cursor: not-allowed;
  opacity: 0.5;
}

.ws-switch__input {
  position: absolute;
  top: 50%;
  left: 0;
  width: max(var(--ws-switch-width), var(--ws-target-min));
  height: var(--ws-target-min);
  margin: 0;
  opacity: 0;
  transform: translateY(-50%);
  cursor: inherit;
}

.ws-switch__track {
  position: relative;
  flex: none;
  pointer-events: none;
  width: var(--ws-switch-width);
  height: var(--ws-switch-height);
  border-radius: var(--ws-radius-full);
  background: var(--ws-color-field-line);
  transition: background-color var(--ws-duration) var(--ws-ease);
}

.ws-switch__thumb {
  position: absolute;
  top: var(--ws-switch-pad);
  left: var(--ws-switch-pad);
  width: var(--ws-switch-thumb);
  height: var(--ws-switch-thumb);
  border-radius: var(--ws-radius-full);
  background: var(--ws-color-panel);
  transition:
    transform var(--ws-duration) var(--ws-ease),
    width var(--ws-duration-fast) var(--ws-ease);
}

.ws-switch__input:checked + .ws-switch__track {
  background: var(--ws-color-accent-hover);
}

.ws-switch__input:checked + .ws-switch__track .ws-switch__thumb {
  transform: translateX(var(--ws-switch-travel));
}

.ws-switch__input:not(:disabled):hover + .ws-switch__track {
  background: var(--ws-color-text-muted);
}

.ws-switch__input:not(:disabled):checked:hover + .ws-switch__track {
  background: var(--ws-color-accent-hover);
}

/* The thumb stretches while pressed, toward the side it will travel to. */
.ws-switch__input:not(:disabled):active + .ws-switch__track .ws-switch__thumb {
  width: calc(var(--ws-switch-thumb) + 4px);
}

.ws-switch__input:not(:disabled):checked:active + .ws-switch__track .ws-switch__thumb {
  transform: translateX(calc(var(--ws-switch-travel) - 4px));
}

.ws-switch__input:focus-visible + .ws-switch__track {
  outline: var(--ws-focus-width) solid var(--ws-color-focus);
  outline-offset: var(--ws-focus-offset);
}

.ws-switch__text {
  display: grid;
  gap: 2px;
  min-width: 0;
}

.ws-switch__label {
  font-weight: var(--ws-weight-medium);
}

.ws-switch__description {
  color: var(--ws-color-text-muted);
  font-size: var(--ws-text-sm);
  line-height: var(--ws-leading-tight);
}

@media (forced-colors: active) {
  .ws-switch__track {
    outline: 1px solid CanvasText;
    forced-color-adjust: none;
  }

  .ws-switch__thumb {
    background: CanvasText;
    forced-color-adjust: none;
  }

  .ws-switch__input:checked + .ws-switch__track {
    background: Highlight;
  }

  .ws-switch__input:checked + .ws-switch__track .ws-switch__thumb {
    background: HighlightText;
  }
}
